/* Materiale didattico Java P1: domande originali e varianti ragionate. */
(() => {
  const foundations = [], input = [];
  function add(bank, topic, type, prompt, code, choices, explanation, steps, tip, trace) {
    const n = bank.length + 1;
    const rotated = choices.map(([text, why], i) => ({text:String(text), why, correct:i===0}));
    for(let i=0;i<n%4;i++) rotated.push(rotated.shift());
    bank.push({id:`${topic}-${String(n).padStart(3,'0')}`,type,prompt,code,options:rotated.map(x=>x.text),answer:rotated.findIndex(x=>x.correct),explanation,steps,optionExplanations:rotated.map(x=>x.why),tip,...(trace?{trace}: {})});
  }
  function theory(bank, topic, p, correct, wrong, explanation, tip) {
    add(bank,topic,'teoria',p,'',[[correct,explanation],...wrong.map(([a,b])=>[a,b])],explanation,[`Individua il concetto richiesto: ${p}`,explanation,`Ricorda: ${tip}`],tip);
  }
  const f = (p,c,w,e,t) => theory(foundations,'fondamenti',p,c,w,e,t);
  f('Quale sequenza descrive l’esecuzione tradizionale di un programma Java?', '.java → javac → .class → JVM', [['.class → javac → .java → JVM','Il sorgente è .java; .class è il risultato della compilazione, non il suo input.'],['.java → browser → .html','Java non richiede un browser e non produce HTML durante la normale compilazione.'],['.java → JVM → javac','La JVM esegue il bytecode dopo la compilazione, non prima.']], 'javac controlla e compila il sorgente .java in bytecode .class. La JVM della piattaforma esegue poi il bytecode; può anche compilarne parti in codice macchina durante l’esecuzione.', 'Prima compili con javac, poi esegui con java.');
  f('Perché Java è portabile?', 'Il bytecode può essere eseguito da una JVM compatibile sulla piattaforma di destinazione', [['Ogni processore esegue direttamente i file .java','Il processore non interpreta direttamente il linguaggio Java.'],['Non usa mai il sistema operativo','La JVM interagisce con il sistema operativo.'],['Tutte le JVM sono lo stesso file binario','La JVM ha implementazioni diverse per le diverse piattaforme.']], 'Il programma distribuisce bytecode e la JVM adatta l’esecuzione alla piattaforma. Occorrono una versione della JVM compatibile e le eventuali dipendenze del programma.', 'Stesso bytecode, JVM adatta al sistema.');
  f('Quale strumento compila il sorgente Java?', 'javac', [['java','Il comando java avvia la JVM, mentre javac compila.'],['Scanner','Scanner legge dati: non è un compilatore.'],['println','println è un metodo di output.']], 'javac è il compilatore incluso nel JDK: legge un file .java e può produrre uno o più file .class.', 'La c finale di javac ricorda compiler.');
  f('Qual è il ruolo principale della JVM?', 'Eseguire il bytecode Java', [['Scrivere automaticamente il sorgente','La JVM esegue, non scrive il programma.'],['Essere un editor di testo','Un editor modifica i file; la JVM esegue il codice compilato.'],['Sostituire tutte le librerie','La JVM non sostituisce le API della libreria standard.']], 'La Java Virtual Machine carica e verifica le classi e ne esegue il bytecode, gestendo servizi come memoria e garbage collection.', 'JVM = macchina virtuale che esegue.');
  f('Che cosa serve per sviluppare e compilare in Java?', 'Un JDK', [['Solo un editor grafico','L’editor permette di scrivere, ma serve anche il compilatore.'],['Solo un browser','Il browser non include necessariamente un compilatore Java.'],['Solo i file .class','I .class sono risultati di compilazione, non strumenti di sviluppo.']], 'Il JDK contiene gli strumenti di sviluppo, tra cui javac, e i componenti necessari all’esecuzione. Un IDE può usare un JDK installato o gestirlo per te.', 'Per sviluppare cerca Development nel nome JDK.');
  f('Che cosa indica runtime?', 'Il periodo in cui il programma è in esecuzione', [['Solo il momento della scrittura','La scrittura precede l’esecuzione.'],['Il nome del file sorgente','Il file sorgente termina normalmente in .java.'],['L’elenco degli import','Gli import sono dichiarazioni del sorgente, non il periodo di esecuzione.']], 'Un errore di sintassi viene normalmente rilevato in compilazione; una divisione intera per zero può invece causare un’eccezione a runtime.', 'Compilazione: preparo. Runtime: eseguo.');
  f('Quale relazione c’è tra classe e oggetto?', 'La classe è un modello; l’oggetto è una sua istanza', [['Sono sempre la stessa cosa','Una classe può descrivere molti oggetti distinti.'],['Un oggetto è un file .java','L’oggetto esiste in memoria; il file contiene sorgente.'],['Una classe contiene solo numeri','Una classe può dichiarare campi, metodi e costruttori.']], 'Una classe descrive dati e comportamenti. Con new si può creare un oggetto di quel tipo e chiamare i metodi di istanza attraverso un riferimento.', 'Classe = progetto; oggetto = esemplare.');
  f('Nel main tradizionale, che cosa significa static?', 'Il metodo appartiene alla classe ed è invocabile senza creare un’istanza', [['Il metodo non esegue istruzioni','static non disattiva il corpo del metodo.'],['Il metodo può essere chiamato una sola volta','static non limita il numero delle chiamate.'],['Tutte le variabili diventano costanti','Una costante si dichiara con final, non con static.']], 'La JVM può invocare main sulla classe senza costruire prima un oggetto. Static non significa né costante né eseguito una sola volta.', 'static: classe; final: vincolo di riassegnazione.');
  f('Che cosa significa void nella firma di main?', 'Il metodo non restituisce un valore', [['Restituisce sempre zero','void non è int: non restituisce zero.'],['Non può contenere istruzioni','Un metodo void può eseguire numerose istruzioni.'],['Non può stampare','Stampare è un effetto, diverso dal restituire un valore.']], 'Un metodo void può stampare, modificare lo stato e usare return; per uscire, ma non restituisce un valore al chiamante.', 'Stampare e restituire sono azioni diverse.');
  f('Che cosa contiene String[] args nel main?', 'Gli argomenti passati da riga di comando', [['Tutto ciò che l’utente digita dopo l’avvio','Per l’input durante l’esecuzione puoi usare Scanner su System.in.'],['Solo numeri già convertiti in int','Gli argomenti sono stringhe: i numeri vanno convertiti.'],['Il testo completo del programma','args non contiene il sorgente.']], 'Avviando java App ciao 12, args contiene due stringhe: "ciao" e "12". Il nome della classe non è un elemento di args.', 'args[0] è il primo argomento, non il nome del programma.');
  f('Che cosa fa import java.util.Scanner;?', 'Permette di usare il nome semplice Scanner per quella classe', [['Copia tutto il codice di Scanner nel main','L’import risolve i nomi: non incolla il codice nel metodo.'],['Crea uno Scanner','Per creare un’istanza serve new Scanner(...).'],['Legge immediatamente una riga','La lettura avviene chiamando un metodo come nextLine().']], 'import collega il nome semplice Scanner al nome completo java.util.Scanner. L’istanza si crea separatamente e i dati si leggono con i suoi metodi.', 'Importare, costruire e leggere sono tre operazioni diverse.');
  f('Quale package è importato implicitamente nei normali file Java?', 'java.lang', [['java.util','Scanner in java.util richiede import o nome completo.'],['java.io','Le classi java.io non sono tutte importate automaticamente.'],['Tutti i package','Importare automaticamente tutto causerebbe ambiguità tra i nomi.']], 'String, System e Math appartengono a java.lang, importato implicitamente. Scanner appartiene invece a java.util.', 'String e Math si usano senza import esplicito.');
  f('Che cos’è un package?', 'Uno spazio dei nomi che raggruppa tipi correlati', [['Un sinonimo di oggetto','Il package organizza i tipi; l’oggetto è un’istanza.'],['Una chiamata di metodo','La dichiarazione package non invoca metodi.'],['Un valore numerico','Un package è un’organizzazione dei nomi.']], 'Il package permette di organizzare classi e ridurre i conflitti tra nomi. La dichiarazione package, quando presente, viene prima degli import.', 'Prima package, poi import, poi dichiarazioni dei tipi.');
  f('Quale istruzione è un commento valido su una riga?', '// spiegazione', [['# spiegazione','Il simbolo # non introduce un commento nel sorgente Java.'],['<!-- spiegazione -->','Questa è la sintassi dei commenti HTML.'],['** spiegazione','Due asterischi da soli non aprono un commento Java.']], 'Il commento // termina alla fine della riga. Per commenti su più righe si usa /* ... */; i commenti non vengono eseguiti.', 'Dentro una stringa, // è invece testo normale.');
  f('Quale estensione contiene normalmente il sorgente Java?', '.java', [['.class','Un .class contiene bytecode compilato.'],['.exe','Un .exe non è la normale estensione del sorgente Java.'],['.html','Un file HTML descrive una pagina web.']], 'Il programmatore scrive sorgente nel file .java. Il compilatore può produrre file .class destinati alla JVM.', 'Sorgente .java, bytecode .class.');
  f('Quale estensione identifica normalmente il bytecode Java?', '.class', [['.java','Il .java è sorgente leggibile dal programmatore.'],['.css','Il CSS definisce lo stile delle pagine web.'],['.txt','Un file .txt non identifica il normale risultato di javac.']], 'javac produce file .class contenenti informazioni sulla classe e bytecode. Il comando java li carica usando il nome della classe e il classpath.', 'Il comando è java NomeClasse, senza .class.');
  f('Quale tra questi è un IDE?', 'IntelliJ IDEA', [['int','int è un tipo primitivo, non un ambiente di sviluppo.'],['System.in','System.in è un flusso di input.'],['Math.random()','È una chiamata a un metodo della libreria standard.']], 'Un IDE integra editor, strumenti di compilazione, esecuzione e debug. IntelliJ, Eclipse e NetBeans sono esempi; non sono il linguaggio Java stesso.', 'IDE aiuta a lavorare; JDK fornisce gli strumenti Java.');
  f('Nel modello tradizionale, come si chiama il punto di ingresso?', 'main', [['startQuiz','Un nome arbitrario non è il punto di ingresso tradizionale di Java.'],['Main','Java distingue maiuscole e minuscole: Main e main sono nomi diversi.'],['println','println è un metodo di output chiamabile da main.']], 'Nel percorso Java 21 tradizionale usato qui, il launcher cerca public static void main(String[] args). La grafia e la firma contano.', 'main è minuscolo, String ha la S maiuscola.');
  f('Quale affermazione sui nomi Java è corretta?', 'Java distingue maiuscole e minuscole', [['main e Main sono identici','Sono identificatori diversi.'],['System e system sono sempre intercambiabili','La classe standard è System con S maiuscola.'],['Il compilatore corregge automaticamente ogni maiuscola','Il compilatore normalmente segnala simboli non trovati.']], 'Java è case-sensitive: System.out.println è corretto, mentre system.out.println cerca un nome diverso che potrebbe non esistere.', 'Copia i nomi delle API rispettando le maiuscole.');
  f('Perché nel corso Java è descritto come linguaggio ibrido?', 'Il sorgente è compilato in bytecode poi eseguito dalla JVM', [['È metà HTML e metà CSS','Questi sono linguaggi del web, non le fasi di esecuzione Java.'],['Non richiede alcuna compilazione','Nel flusso tradizionale javac compila il sorgente.'],['È sempre più lento di ogni linguaggio compilato','La classificazione non stabilisce un confronto assoluto di prestazioni; esiste anche il JIT.']], 'Il modello didattico distingue una prima compilazione in formato intermedio e la successiva esecuzione tramite macchina virtuale. Le JVM moderne possono usare compilazione JIT.', 'Ibrido descrive il percorso del codice, non una garanzia di velocità.');

  const names=['Ada','Luca','Mia','Noah','Sara','Leo','Emma','Ivo'];
  for(let k=0;k<8;k++) {
    const name=names[k], cls=`Saluto${k+1}`, a=k+2, b=k+4;
    add(foundations,'fondamenti','codice',`Con il comando java ${cls} ${name} Java, che cosa stampa il programma?`,`public class ${cls} {\n  public static void main(String[] args) {\n    System.out.println(args[0]);\n  }\n}`,[[name,`args[0] è la prima stringa dopo il nome della classe: ${name}.`],['Java','Java è il secondo argomento, accessibile con args[1].'],[cls,'Il nome della classe non è inserito nell’array args.'],['0','Lo zero è l’indice usato, non il contenuto della posizione.']],`La JVM costruisce args con gli argomenti del comando. Qui contiene ["${name}", "Java"]. L’indice zero seleziona il primo elemento: si stampa ${name}.`,['Ignora java e il nome della classe quando costruisci args.',`Scrivi args[0] = "${name}" e args[1] = "Java".`,'Esegui println con il valore selezionato.'],'Numera gli argomenti a partire da zero.');
    add(foundations,'fondamenti','codice',`Si avvia java ${cls} ${Array.from({length:k+1},(_,i)=>`p${i}`).join(' ')}. Quale numero viene stampato?`,`public class ${cls} {\n  public static void main(String[] args) {\n    System.out.println(args.length);\n  }\n}`,[[`${k+1}`,`Sono presenti ${k+1} argomenti dopo il nome della classe.`],[`${k+2}`,'Hai contato anche il nome della classe, che non appartiene ad args.'],[`${k}`,'length è il numero degli elementi, non l’ultimo indice valido.'],['Errore di compilazione','Il codice è valido: args.length è una proprietà disponibile su ogni array.']],`args.length conta gli argomenti e vale ${k+1}. Gli indici vanno da 0 a ${k}; il nome ${cls} e il comando java non entrano nel conteggio.`,['Separa il nome della classe dagli argomenti.',`Conta i token p0 fino a p${k}.`,`La lunghezza è ${k+1}, mentre l’ultimo indice è ${k}.`],'Lunghezza e ultimo indice differiscono di uno.');
    add(foundations,'fondamenti','debug',`Il file è chiamato ${cls}.java. Perché javac segnala un errore?`,`public class ${cls}Extra {\n  public static void main(String[] args) {\n    System.out.println("${name}");\n  }\n}`,[['Il nome della classe pubblica non coincide con il nome del file',`La classe pubblica ${cls}Extra deve trovarsi in ${cls}Extra.java.`],['main non può stampare stringhe','println può stampare una String.'],['Manca un oggetto per invocare main','main è static: non serve creare un oggetto.'],['String[] args deve essere int[]','Il punto di ingresso tradizionale riceve String[], non int[].']],`Una classe pubblica top-level deve avere lo stesso nome del file, rispettando maiuscole e minuscole. Qui ${cls}.java contiene public class ${cls}Extra: rinomina coerentemente il file o la classe.`,[`Leggi il nome del file: ${cls}.java.`,`Leggi il nome dopo public class: ${cls}Extra.`,'Confrontali: non coincidono, quindi il problema precede l’esecuzione.'],'Controlla sempre la coppia NomeClasse.java / public class NomeClasse.');
    add(foundations,'fondamenti','codice',`Qual è l’output di questo main? Considera ogni println su una nuova riga.`,`public class ${cls} {\n  public static void main(String[] args) {\n    // System.out.println("${name}");\n    System.out.println("Java ${k+1}");\n    /* System.out.println("Fine"); */\n  }\n}`,[[`Java ${k+1}`,'Le altre due stampe sono commentate e non vengono eseguite.'],[`${name}\nJava ${k+1}\nFine`,'Hai eseguito anche il testo racchiuso nei commenti.'],[`${name}`,'Quella istruzione è dopo // e quindi è ignorata.'],['Fine','La stampa di Fine è dentro /* ... */, quindi non viene eseguita.']],`I commenti spiegano o disattivano temporaneamente del sorgente; non sono istruzioni eseguite. Rimane una sola chiamata effettiva a println, che stampa Java ${k+1}.`,['Scarta il testo da // fino a fine riga.','Scarta il blocco tra /* e */.',`Esegui soltanto System.out.println("Java ${k+1}").`],'Prima di simulare il codice, riconosci commenti e stringhe.');
    add(foundations,'fondamenti','debug',`Il codice compila. Con java ${cls}, perché non si avvia dal punto di ingresso tradizionale?`,`public class ${cls} {\n  public void main(String[] args) {\n    System.out.println("${name}");\n  }\n}`,[['A main manca static','La firma del launcher tradizionale richiede public static void main(String[] args).'],['Manca import java.lang.String','java.lang è importato implicitamente: non serve questo import.'],['Il nome della classe è troppo lungo','Il nome usato è un identificatore valido.'],['println non è ammesso nel main','println può essere usato nel main.']],`Questo è un metodo di istanza chiamato main, ma non il punto di ingresso tradizionale richiesto dal comando java in Java 21 senza funzioni preview. Aggiungendo static si ottiene la firma corretta.`,['Distingui compilazione ed esecuzione: un normale metodo di istanza può compilare.','Confronta la firma con public static void main(String[] args).','La parola assente è static.'],'Un file compilabile non garantisce che abbia il main richiesto dal launcher.');
    add(foundations,'fondamenti','debug',`Qual è il primo problema in questo frammento di ${cls}?`,`public class ${cls} {\n  public static void main(String[] args) {\n    system.out.println("${name}");\n  }\n}`,[['system deve essere scritto System','Il nome della classe standard ha la S maiuscola.'],['La stringa deve usare apici singoli','Le stringhe Java usano doppi apici; gli apici singoli indicano char.'],['main deve essere scritto Main','Il metodo di ingresso si chiama main minuscolo.'],['args deve essere eliminato','String[] args è un parametro valido e richiesto nella forma tradizionale.']],`Java distingue le maiuscole: system non risolve la classe System. La correzione è System.out.println("${name}");. Non serve cambiare né il testo né gli argomenti di main.`,['Cerca i nomi delle API standard.','Confronta system con System.','Correggi la maiuscola e ricompila.'],'Un errore “cannot find symbol” può dipendere da una sola maiuscola.');
    add(foundations,'fondamenti','codice',`Quale file di bytecode produce normalmente javac ${cls}.java, se questa è l’unica classe dichiarata?`,`public class ${cls} {\n  public static void main(String[] args) {\n    System.out.println(${a});\n  }\n}`,[[`${cls}.class`,'javac produce il bytecode della classe in un file con estensione .class.'],[`${cls}.exe`,'La compilazione standard con javac non genera un eseguibile Windows .exe.'],[`${cls}.html`,'javac non trasforma il programma in una pagina web.'],[`${cls}.java.class.txt`,'L’estensione standard è semplicemente .class.']],`Il file ${cls}.java è il sorgente. javac analizza il codice e genera ${cls}.class. Per lanciare il programma si usa java ${cls}, senza specificare l’estensione .class.`,['Individua il nome della classe pubblica.','Mantieni quel nome e sostituisci .java con .class.',`Avvia poi java ${cls}.`],'javac compila il file; java avvia la classe.');
    add(foundations,'fondamenti','codice',`Il file ${cls}.class è nella cartella corrente e non usa package. Quale comando avvia il programma?`,`public class ${cls} {\n  public static void main(String[] args) {\n    System.out.println("Avvio ${k+1}");\n  }\n}`,[[`java ${cls}`,'Il launcher riceve il nome della classe, senza estensione.'],[`java ${cls}.class`,'Nel lancio tradizionale non si aggiunge .class al nome.'],[`javac ${cls}.class`,'javac compila sorgente .java, non esegue .class.'],[`run ${cls}.java`,'run non è il comando standard del JDK per avviare questa classe.']],`Dopo aver compilato, java carica la classe ${cls} dal classpath. In questa situazione semplice la cartella corrente è sufficiente e si usa java ${cls}.`,['Verifica che la compilazione abbia creato il .class.','Scegli il comando di esecuzione java, non javac.','Passa il nome della classe senza .class.'],'Non confondere il nome del file con il nome usato dal launcher.');
    add(foundations,'fondamenti','codice',`Il codice non contiene alcun import. Quale affermazione è corretta?`,`public class ${cls} {\n  public static void main(String[] args) {\n    System.out.println(Math.max(${a}, ${b}));\n  }\n}`,[['Compila: System e Math appartengono a java.lang','java.lang è importato implicitamente e Math.max accetta due int.'],['Non compila: serve import java.math.Math','La classe è java.lang.Math, non java.math.Math.'],['Non compila: ogni classe richiede un import esplicito','Le classi di java.lang sono disponibili implicitamente.'],['Compila solo dentro un IDE','Un JDK può compilare questo codice anche da terminale.']],`System e Math sono classi di java.lang, disponibile senza import esplicito. Math.max confronta ${a} e ${b} e restituisce ${b}; println visualizza quel risultato.`,['Controlla a quale package appartiene Math.','Ricorda l’import implicito di java.lang.',`Confronta ${a} e ${b}: il maggiore è ${b}.`],'java.math contiene altre classi, come BigInteger; Math è in java.lang.');
    add(foundations,'fondamenti','codice',`Il comando è java ${cls} ${name} ${a}. Che cosa stampa questa istruzione?`,`public class ${cls} {\n  public static void main(String[] args) {\n    System.out.println(args[1] + args[1]);\n  }\n}`,[[`${a}${a}`,'args contiene String: il simbolo + concatena due testi.'],[`${a*2}`,'Sarebbe il doppio numerico, ma qui non avviene una conversione in int.'],[`${name}${name}`,'Il nome è args[0], mentre il codice legge args[1].'],['Errore: gli argomenti non possono contenere numeri','Gli argomenti possono contenere cifre; sono comunque stringhe.']],`args[1] vale la stringa "${a}". Il + tra String concatena e produce "${a}${a}": non calcola ${a}+${a}. Per una somma numerica bisognerebbe prima convertire con Integer.parseInt.`,[`Ricostruisci args: ["${name}", "${a}"].`,'Leggi args[1] come testo, non come int.',`Unisci "${a}" e "${a}" ottenendo "${a}${a}".`],'Gli argomenti della riga di comando arrivano sempre come stringhe.');
  }

  const q=(p,c,w,e,t)=>theory(input,'input',p,c,w,e,t);
  q('Quale metodo di Scanner legge un singolo token?', 'next()', [['nextLine()','nextLine legge il resto della riga, compresi gli spazi.'],['println()','println stampa su un flusso di output, non legge.'],['readTokenInt()','Questo non è un metodo standard di Scanner.']], 'next() usa i delimitatori dello Scanner, che per impostazione predefinita sono gli spazi bianchi. Legge un token e lascia quelli successivi disponibili.', 'Token = una porzione separata dai delimitatori.');
  q('Quale metodo di Scanner legge un’intera riga?', 'nextLine()', [['next()','next si arresta al delimitatore e non legge l’intera riga con spazi.'],['nextInt()','nextInt prova a convertire il prossimo token in un intero.'],['print()','print scrive in output.']], 'nextLine() restituisce il testo fino al separatore di riga, escluso il separatore, e sposta la posizione dopo di esso. Può quindi restituire anche una stringa vuota.', 'La fine riga viene consumata, ma non fa parte della String restituita.');
  q('Quale dichiarazione legge correttamente un intero?', 'int eta = s.nextInt();', [['int eta = s.nextLine();','nextLine restituisce String, non int.'],['String eta = s.nextInt();','nextInt restituisce int: non c’è conversione implicita a String in questa assegnazione.'],['int eta = System.out.println();','println non restituisce un int e non legge input.']], 'nextInt() legge un token e lo interpreta come int. Se il token non è un intero valido può lanciare InputMismatchException: non restituisce automaticamente zero.', 'Associa il metodo al tipo restituito.');
  q('Quale costruttore collega Scanner alla tastiera tramite lo standard input?', 'new Scanner(System.in)', [['new Scanner(System.out)','System.out è output; non è il flusso di input richiesto da questo costruttore.'],['new Scanner()','Scanner non dispone di un costruttore standard senza argomenti.'],['Scanner.nextInt(System.in)','nextInt è un metodo di lettura su un oggetto Scanner, non il suo costruttore.']], 'System.in è il flusso standard di input. new Scanner(System.in) costruisce un oggetto che può analizzarne il contenuto in token o righe.', 'Prima crei Scanner, poi chiami nextInt o nextLine.');
  q('Qual è la differenza principale tra print e println?', 'println aggiunge un separatore di riga dopo il valore', [['print non può stampare numeri','Entrambi possono stampare numeri tramite gli overload.'],['println legge dalla tastiera','println è output, non input.'],['print aggiunge sempre uno spazio','print non aggiunge automaticamente spazi.']], 'print scrive il valore e lascia la posizione sulla stessa riga; println scrive il valore e aggiunge il separatore di riga del sistema.', 'Gli spazi vanno messi esplicitamente nel testo.');
  q('Quale escape Java indica una nuova riga?', '\\n', [['\\t','\\t indica una tabulazione.'],['\\a','\\a non è un escape valido nelle stringhe Java standard.'],['/n','La barra deve essere un backslash, non uno slash.']], 'All’interno di una stringa Java, \u005cn rappresenta il carattere newline. Si scrive con un backslash seguito da n, non con una barra normale.', 'Non tutti gli escape di altri linguaggi sono validi in Java.');
  q('Quale escape Java indica una tabulazione?', '\\t', [['\\n','\\n indica un ritorno a una nuova riga.'],['\\s\\s','\\s è uno spazio nelle versioni recenti; due spazi non sono una tabulazione.'],['/t','La barra / non introduce un escape Java.']], 'La sequenza \\t inserisce un carattere di tabulazione. La sua larghezza visiva dipende dalla posizione e dai tab stop dell’ambiente di visualizzazione.', 'Una tabulazione non equivale sempre a un numero fisso di spazi.');
  q('Quale metodo legge un valore booleano con Scanner?', 'nextBoolean()', [['nextBool()','Il nome completo dell’API è nextBoolean().'],['nextInt()','Legge un intero e non tratta automaticamente 0/1 come false/true.'],['nextLineBoolean()','Non è un metodo standard di Scanner.']], 'nextBoolean() riconosce i token true e false senza distinguere le maiuscole. Per input come sì o 1 serve una gestione diversa.', 'Scanner non converte automaticamente 1 in true.');
  q('Quale metodo restituisce un valore di tipo double?', 'nextDouble()', [['nextInt()','nextInt restituisce int e non legge un generico numero decimale.'],['next()','next restituisce String.'],['println()','println restituisce void.']], 'nextDouble() legge il prossimo token come double usando il locale dello Scanner. Per il punto decimale in un esempio riproducibile si può impostare useLocale(Locale.US).', 'Il separatore decimale dipende dal locale.');
  q('Che cosa succede normalmente con nextInt() se il prossimo token è ciao?', 'Viene lanciata InputMismatchException', [['Restituisce sempre 0','Scanner non sostituisce automaticamente input non validi con zero.'],['Restituisce la stringa ciao','Il tipo restituito è int, non String.'],['Salta automaticamente ogni parola fino al numero','nextInt non cerca arbitrariamente oltre un token non valido.']], 'Il token ciao non è convertibile in int. Scanner segnala il problema con InputMismatchException; si può controllare hasNextInt() e consumare l’input non valido.', 'Validare l’input evita sorprese a runtime.');
  q('Dopo nextInt(), perché nextLine() può restituire una stringa vuota?', 'Il separatore di riga dopo il numero non è ancora stato consumato', [['nextLine non funziona con Scanner','Funziona, ma parte dalla posizione corrente nel flusso.'],['Tutte le stringhe sono vuote dopo un numero','È un problema di posizione nel flusso, non una regola delle stringhe.'],['nextInt chiude automaticamente System.in','nextInt non chiude lo Scanner né il flusso.']], 'nextInt consuma il token numerico, non il separatore successivo. Se il separatore è subito una fine riga, nextLine legge il resto vuoto di quella riga e consuma la fine riga.', 'Disegna il cursore subito dopo le cifre, prima dell’Invio.');
  q('Quale combinazione può leggere nome completo e poi età, nell’ordine indicato?', 'String nome = s.nextLine(); int eta = s.nextInt();', [['String nome = s.next(); int eta = s.nextInt();','next legge solo la prima parola: con un nome completo la successiva lettura numerica trova il cognome.'],['int nome = s.nextInt(); String eta = s.nextLine();','I tipi e l’ordine non rispettano i dati richiesti.'],['String nome = s.nextInt(); int eta = s.nextLine();','I tipi restituiti dai metodi sono incompatibili con le variabili.']], 'Quando il nome è la prima riga, nextLine lo legge compresi gli spazi. Poi nextInt legge il token numerico della riga seguente. L’ordine evita il problema della fine riga lasciata da una lettura numerica precedente.', 'Scegli nextLine per i nomi che possono contenere spazi.');
  q('Quale import rende disponibile il nome Scanner?', 'import java.util.Scanner;', [['import java.lang.Scanner;','Scanner non appartiene a java.lang.'],['include <Scanner>','Questa non è la sintassi degli import Java.'],['import Scanner from java;','Questa non è una dichiarazione import Java valida.']], 'Scanner è la classe java.util.Scanner. In alternativa all’import si può usare ogni volta il suo nome completo.', 'Gli import Java terminano con un punto e virgola.');
  q('Che cosa fa System.out.println() senza argomenti?', 'Stampa soltanto un separatore di riga', [['Stampa la parola null','Non viene passato alcun valore da stampare.'],['Non compila','PrintStream ha un overload println() senza argomenti.'],['Legge una riga','È un metodo di output.']], 'L’overload senza argomenti aggiunge una fine riga. È utile per terminare una riga costruita con più chiamate print o per inserire una riga vuota.', 'Una chiamata println() è valida anche senza testo.');
  q('Qual è il tipo restituito da nextLine()?', 'String', [['char','Una riga può contenere molti caratteri, non un solo char.'],['int','Per ottenere un int bisogna usare una lettura/conversione numerica.'],['void','nextLine restituisce il testo letto.']], 'nextLine restituisce una String, anche se il testo contiene soltanto cifre. Il contenuto "25" rimane testo finché non viene convertito.', 'Le cifre dentro una String non diventano automaticamente numeri.');
  q('Quale metodo legge un intero più grande del range int, purché nel range long?', 'nextLong()', [['nextInt()','Un valore fuori dal range int causa un problema di conversione.'],['nextLarge()','Non è un metodo standard di Scanner.'],['nextLineInt()','Non è un metodo standard di Scanner.']], 'nextLong() restituisce long, un intero a 64 bit. Serve anche una variabile long per conservare il risultato senza restringimento.', 'Tipo della variabile e tipo del metodo devono essere compatibili.');
  q('Che cosa verifica s.hasNextInt()?', 'Se il prossimo token è interpretabile come int, senza consumarlo', [['Legge e scarta sempre il numero','hasNextInt controlla senza avanzare oltre il token.'],['Se tutta la riga contiene soltanto numeri','Controlla il prossimo token, non tutta la riga.'],['Se lo Scanner è già stato chiuso','Il controllo riguarda il prossimo input numerico.']], 'hasNextInt è utile per validare l’input. Dopo un true occorre comunque chiamare nextInt per consumare il numero; dopo un false si può gestire il token non valido.', 'hasNext... controlla; next... consuma.');
  q('Quale istruzione stampa esattamente una barra rovesciata?', 'System.out.print("\\\\");', [['System.out.print("/");','Questa stampa uno slash normale, non un backslash.'],['System.out.print("\\n");','Questa inserisce una nuova riga.'],['System.out.print("\\t");','Questa inserisce una tabulazione.']], 'Nelle stringhe Java il backslash introduce escape. Per rappresentare un singolo backslash letterale se ne scrivono due nel sorgente: "\\\\".', 'Un backslash nel risultato richiede due backslash nel sorgente.');
  q('Con il locale US, quale token può essere letto come double?', '3.5', [['tre e mezzo','Le parole non rappresentano direttamente un double per Scanner.'],['3,5','Nel locale US la virgola non è il separatore decimale.'],['3.5.2','Un numero non può contenere due separatori decimali.']], 'Impostando esplicitamente Locale.US si usa il punto come separatore decimale. Il locale del sistema può essere diverso: gli esercizi con numeri decimali lo precisano.', 'Per esempi riproducibili dichiara sempre il locale.');
  q('Qual è il rischio di chiudere uno Scanner costruito con System.in?', 'Si chiude anche lo standard input sottostante', [['Tutti gli output vengono cancellati','La chiusura dell’input non cancella ciò che è già stato stampato.'],['Si disinstalla Java','close non modifica l’installazione del JDK.'],['Il programma viene ricompilato','close riguarda risorse a runtime.']], 'Scanner.close chiude la sorgente se questa è Closeable. Con System.in questo può impedire letture successive; va gestito il ciclo di vita della risorsa nel contesto del programma.', 'Non creare e chiudere ripetutamente Scanner sullo stesso System.in.');

  for(let k=0;k<8;k++) {
    const name=names[k], a=k+3,b=k+5;
    add(input,'input','codice',`Con input ${a} ${b}, che cosa stampa il frammento? Si assumono import corretti.`,`Scanner s = new Scanner("${a} ${b}");\nint x = s.nextInt();\nint y = s.nextInt();\nSystem.out.println(x + y);`,[[`${a+b}`,'Entrambi i valori sono int: + esegue la somma.'],[`${a}${b}`,'La concatenazione richiederebbe una String; qui x e y sono int.'],[`${a}`,'La stampa usa x + y, non solo x.'],[`${b}`,'La stampa usa entrambi i numeri, non solo il secondo.']],`Il primo nextInt legge ${a}; il secondo legge ${b}. Le variabili sono entrambe int, perciò x + y calcola ${a+b} e non concatena le cifre.`,[`x riceve ${a}.`,`y riceve ${b}.`,`Calcola ${a} + ${b} = ${a+b}.`],'Prima individua il tipo, poi interpreta il simbolo +.',{headers:['Lettura','Valore','Tipo'],rows:[['nextInt 1',String(a),'int'],['nextInt 2',String(b),'int'],['x + y',String(a+b),'int']]});
    add(input,'input','codice',`Lo Scanner contiene il nome completo mostrato. Quale testo stampa next()?`,`Scanner s = new Scanner("${name} Rossi");\nSystem.out.println(s.next());`,[[name,'next legge soltanto il primo token prima dello spazio.'],[`${name} Rossi`,'Il nome completo richiederebbe nextLine.'],['Rossi','Rossi è il secondo token: il primo non è ancora stato consumato.'],['Stringa vuota','Lo Scanner si trova all’inizio di un token non vuoto.']],`Con il delimitatore predefinito, lo spazio separa i token. next legge ${name} e si arresta prima di Rossi, che rimane disponibile per una lettura successiva.`,['Localizza il primo spazio.',`Il token prima dello spazio è ${name}.`,'Stampa solo quel token.'],'next legge una parola; nextLine legge il resto della riga.');
    add(input,'input','codice',`Che cosa stampa nextLine() nello stesso tipo di input?`,`Scanner s = new Scanner("${name} Rossi");\nSystem.out.println(s.nextLine());`,[[`${name} Rossi`,'nextLine conserva gli spazi interni e legge fino alla fine della riga.'],[name,'Questo sarebbe il primo token letto da next, non l’intera riga.'],['Rossi','Nessuna lettura precedente ha già consumato il nome.'],['null','La riga esiste: non si tratta della fine di un flusso letto da BufferedReader.']],`nextLine parte dall’inizio dell’input e restituisce tutto il testo fino alla fine della riga o dell’input. Lo spazio tra ${name} e Rossi è incluso nella String.`,['La posizione iniziale precede il nome.','Non ci sono separatori di riga prima della fine.',`La String risultante è "${name} Rossi".`],'Gli spazi interni non fermano nextLine.');
    add(input,'input','codice','Che cosa viene stampato tra parentesi quadre? Il sorgente contiene un escape di nuova riga. ',`Scanner s = new Scanner("${a}\\n${name}\\n");\nint eta = s.nextInt();\nString nome = s.nextLine();\nSystem.out.println("[" + nome + "]");`,[['[]','nextLine legge il resto vuoto della prima riga, dopo il token numerico.'],[`[${name}]`,'Questo richiederebbe consumare prima il separatore dopo il numero.'],[`[${a}]`,'Il numero è già stato consumato da nextInt.'],['[null]','nextLine restituisce qui una String vuota, non null.']],`nextInt consuma ${a}, lasciando il cursore subito prima del separatore di riga. nextLine trova zero caratteri prima di quel separatore: restituisce "" e lo consuma. Il nome ${name} è ancora nella riga successiva.`,[`Leggi ${a} come int.`,'Il cursore rimane prima di \\n.','nextLine legge il resto vuoto e quindi si stampa [].'],'La parentesi quadra è utile per rendere visibili le stringhe vuote.');
    add(input,'input','codice','Dopo questa gestione della fine riga, quale nome viene stampato?',`Scanner s = new Scanner("${a}\\n${name} Rossi\\n");\nint eta = s.nextInt();\ns.nextLine();\nString nome = s.nextLine();\nSystem.out.println(nome);`,[[`${name} Rossi`,'La prima nextLine scarta il resto vuoto, la seconda legge il nome completo.'],[name,'La lettura usa nextLine: non si ferma allo spazio.'],['Stringa vuota','Solo la prima chiamata nextLine restituisce il resto vuoto.'],[`${a}`,'Il valore numerico è già stato letto da nextInt e non viene stampato.']],`La chiamata s.nextLine() senza assegnazione consuma la fine della riga del numero. La chiamata seguente parte dalla riga del nome e legge ${name} Rossi per intero.`,['Leggi il numero.','Consuma il resto della prima riga con una nextLine dedicata.','Leggi il nome completo con la nextLine successiva.'],'Una lettura aggiuntiva può servire per consumare la fine riga, non un dato.');
    add(input,'input','codice','Qual è l’output completo? Le righe sono separate da una nuova riga.',`System.out.print("${name}");\nSystem.out.print("-${a}");\nSystem.out.println("!");\nSystem.out.print("Fine");`,[[`${name}-${a}!\nFine`,'I due print e il primo println compongono la stessa riga; solo println va a capo.'],[`${name}\n-${a}\n!\nFine`,'print non aggiunge una nuova riga dopo ogni chiamata.'],[`${name}-${a}!Fine`,'Hai ignorato la fine riga aggiunta da println.'],[`${name} -${a} !\nFine`,'Le stampe non aggiungono automaticamente spazi.']],`print scrive senza avanzare di riga. Le prime tre chiamate producono ${name}-${a}!, poi println aggiunge la fine riga. L’ultimo print scrive Fine sulla seconda riga.`,[`Prima stampa: ${name}, senza fine riga.`,`Seconda stampa: aggiunge -${a}.`,'println aggiunge ! e una fine riga.','L’ultimo print scrive Fine.'],'Per simulare l’output tieni un cursore e spostalo solo quando previsto.');
    add(input,'input','codice','Quale testo viene stampato? Le virgolette non fanno parte dell’output.',`Scanner s = new Scanner("${a} ${b}");\nString x = s.next();\nString y = s.next();\nSystem.out.println(x + y);`,[[`${a}${b}`,'next restituisce String anche quando legge solo cifre.'],[`${a+b}`,'Una somma numerica richiederebbe nextInt o una conversione.'],[`${a} ${b}`,'Il delimitatore separa i token ma non viene aggiunto nella concatenazione.'],[`${b}${a}`,'L’ordine della concatenazione è x seguito da y.']],`Le chiamate next restituiscono "${a}" e "${b}" come String. Il simbolo + tra stringhe concatena; lo spazio dell’input non appartiene ai token e non viene ricreato.`,[`x è la String "${a}".`,`y è la String "${b}".`,`x + y produce "${a}${b}".`],'Il contenuto sembra un numero, ma è il tipo a decidere l’operazione.');
    add(input,'input','debug','Quale modifica risolve l’incompatibilità di tipo mantenendo eta di tipo int?',`Scanner s = new Scanner("${a}");\nint eta = s.nextLine();`,[['Sostituire nextLine() con nextInt()','nextInt restituisce int ed è compatibile con la variabile.'],['Aggiungere println prima della lettura','Stampare non cambia il tipo restituito da nextLine.'],['Cambiare int in Int','Il tipo primitivo si scrive int; Int non è il wrapper standard Integer.'],['Togliere il punto e virgola','Il punto e virgola termina correttamente la dichiarazione e non causa il problema.']],`nextLine restituisce String mentre eta richiede int: Java non effettua questa conversione implicitamente. Poiché l’input è un token numerico, eta = s.nextInt() è una soluzione diretta; in alternativa si potrebbe usare Integer.parseInt su una stringa valida.`,['Leggi il tipo della variabile: int.','Leggi il tipo restituito da nextLine: String.','Scegli una lettura o conversione che produca int.'],'Non confondere errore di compilazione per i tipi con errore di lettura a runtime.');
    add(input,'input','codice','Quale sequenza rappresenta l’output? La scritta «a capo» indica una nuova riga.',`System.out.print("${name}\\n${a}");`,[[`${name} → a capo → ${a}`,'L’escape \\n inserisce una fine riga anche usando print.'],[`${name}\\n${a}`,'Il sorgente contiene un escape valido: non stampa letteralmente backslash e n.'],[`${name} ${a}`,'Una nuova riga non è un semplice spazio.'],[`${name}${a}`,'Il carattere newline non viene ignorato.']],`print non aggiunge una nuova riga al termine, ma stampa tutti i caratteri della stringa, incluso il newline rappresentato da \\n. Quindi ${name} e ${a} appaiono su due righe.`,['Distingui i caratteri della stringa dagli effetti del metodo.','Sostituisci mentalmente \\n con una nuova riga.',`Scrivi ${name} sulla prima riga e ${a} sulla seconda.`],'print può comunque andare a capo se il testo contiene \\n.');
    add(input,'input','codice','Quale valore viene stampato dopo il controllo del prossimo token?',`Scanner s = new Scanner("${a} ${b}");\nboolean valido = s.hasNextInt();\nSystem.out.println(s.nextInt());`,[[`${a}`,'hasNextInt controlla il primo token senza consumarlo; nextInt legge ancora il primo.'],[`${b}`,'Questo accadrebbe se il controllo consumasse il primo numero, ma non lo fa.'],['true','Il codice stampa s.nextInt(), non la variabile valido.'],['false','Il primo token è un intero valido e comunque non viene stampato valido.']],`hasNextInt restituisce true perché ${a} è un token int valido, ma lascia il token disponibile. Il nextInt successivo consuma quindi ${a}, non ${b}.`,[`Controlla il token ${a}: è un int valido.`,'Il controllo non sposta la posizione oltre il token.',`nextInt legge ancora ${a} e lo stampa.`],'Le funzioni hasNext... controllano senza consumare il token.');
  }

  window.JAVA_TOPICS.push({id:'fondamenti',title:'Fondamenti di Java',subtitle:'JVM, classi e primo programma',icon:'01',color:'#62cbb0',minutes:14,source:'JAVA P1: introduzione, IDE, linguaggi, librerie e primo programma; Riassunto: sezioni 2–3, pagina 3.',sections:[
    {title:'Dal sorgente alla JVM',text:'Java è un linguaggio orientato agli oggetti. Nel flusso tradizionale scrivi un file .java, lo compili con javac e ottieni bytecode .class. La JVM esegue questo formato sulla piattaforma disponibile. La portabilità richiede una JVM e dipendenze compatibili; non significa che ogni programma possa ignorare sistema operativo o versione.',code:'javac Saluto.java\njava Saluto',steps:['Scrivi e salva il sorgente.','Compila: gli errori di sintassi e molti errori di tipo vengono segnalati qui.','Avvia la classe: le istruzioni del main vengono eseguite.'],tip:'La c di javac ricorda compilazione. java avvia.'},
    {title:'JDK, JVM, runtime e IDE',text:'Il JDK è il kit per sviluppare: comprende javac e gli strumenti per eseguire e diagnosticare programmi. La JVM è il componente che esegue bytecode. JRE indica l’ambiente necessario all’esecuzione; nelle distribuzioni moderne non sempre è un pacchetto separato. Un IDE, come IntelliJ o Eclipse, integra editor e strumenti ma usa comunque un JDK.',code:'// Sorgente: App.java\n// Compilazione: javac App.java\n// Bytecode: App.class\n// Esecuzione: java App',steps:['Per compilare verifica di avere il JDK, non solo un runtime.','Un errore in compilazione impedisce di ottenere il nuovo .class.','Un errore a runtime avviene dopo l’avvio.'],tip:'Immagina il JDK come una cassetta degli attrezzi e la JVM come il motore.'},
    {title:'Il primo programma, riga per riga',text:'La classe pubblica Saluto va nel file Saluto.java. Il main tradizionale è il punto di ingresso: public lo rende accessibile al launcher, static consente di chiamarlo senza un oggetto, void indica che non restituisce un valore. Le parentesi graffe delimitano blocchi; le istruzioni come println terminano con ;.',code:'public class Saluto {\n    public static void main(String[] args) {\n        System.out.println("Ciao Java!");\n    }\n}',steps:['La JVM cerca main nella classe avviata.','Entra nel corpo del main.','println scrive il messaggio e una fine riga.','Alla fine del main il programma semplice termina.'],tip:'Scrivi lo scheletro a memoria, poi verifica maiuscole, parentesi e punto e virgola.'},
    {title:'Classi, oggetti e nomi',text:'Una classe descrive dati e comportamenti; un oggetto è un esemplare concreto di quel modello. I metodi statici appartengono alla classe, quelli di istanza si chiamano su oggetti. Java distingue maiuscole e minuscole: System è diverso da system, main da Main. static non significa costante: per impedire la riassegnazione si usa final.',code:'// main è static: il launcher non deve creare un Saluto.\n// Scanner, invece, si costruisce come oggetto:\njava.util.Scanner lettore = new java.util.Scanner(System.in);',steps:['Individua il nome della classe o del tipo.','Individua il riferimento all’oggetto, se presente.','Leggi la dot notation come destinatario.metodo().'],tip:'Classe = progetto; oggetto = esemplare. Non scambiare static con final.'},
    {title:'Package, import e commenti',text:'I package organizzano i tipi in spazi dei nomi. import permette di usare un nome semplice invece di quello completo; non crea un oggetto e non esegue codice. java.lang è disponibile implicitamente: String, System e Math non richiedono import. I commenti // e /* ... */ non vengono eseguiti.',code:'import java.util.Scanner;\n\npublic class App {\n    public static void main(String[] args) {\n        // Questo è un commento, non viene stampato.\n        Scanner s = new Scanner(System.in);\n        System.out.println("Pronto");\n    }\n}',steps:['L’eventuale dichiarazione package precede gli import.','Gli import precedono la dichiarazione della classe.','Per usare Scanner crea separatamente un’istanza.'],tip:'Math si trova in java.lang, non in java.math.'},
    {title:'Gli argomenti da riga di comando',text:'String[] args contiene soltanto gli argomenti passati dopo il nome della classe. Gli indici partono da zero. Ogni elemento è una String, anche quando contiene cifre: "12" + "3" vale "123". Non confondere gli argomenti iniziali con la lettura da tastiera durante l’esecuzione.',code:'// Comando: java Saluto Ada 12\npublic class Saluto {\n    public static void main(String[] args) {\n        System.out.println(args[0]);  // Ada\n        System.out.println(args[1]);  // 12 (testo)\n        System.out.println(args.length); // 2\n    }\n}',steps:['Escludi il comando java e il nome Saluto.','Associa args[0] ad Ada e args[1] a 12.','La lunghezza è 2, l’ultimo indice valido è 1.'],tip:'Se non passi argomenti, args.length è zero: args[0] non esiste.'}
  ],questions:foundations});
  window.JAVA_TOPICS.push({id:'input',title:'Input e output',subtitle:'Scanner, stringhe e lettura dei dati',icon:'02',color:'#7bbbf2',minutes:15,source:'JAVA P1: programma interattivo, Scanner, output e caratteri speciali; Riassunto: sezione 4, pagine 3–4.',sections:[
    {title:'Prima crea il lettore, poi leggi',text:'Scanner interpreta una sorgente come token o righe. Per la tastiera si collega a System.in. I metodi nextInt, nextLong, nextDouble e nextBoolean restituiscono tipi precisi: la variabile deve essere compatibile. Negli esercizi uso spesso new Scanner("testo") per rendere l’input riproducibile.',code:'import java.util.Scanner;\n\nScanner s = new Scanner(System.in);\nSystem.out.print("Età: ");\nint eta = s.nextInt();\nSystem.out.println("Hai " + eta + " anni");',steps:['import rende visibile il nome Scanner.','new costruisce il lettore.','nextInt legge un token e restituisce int.','println visualizza il risultato.'],tip:'Input e output sono direzioni opposte: System.in entra, System.out esce.'},
    {title:'Una parola o una riga intera?',text:'next() legge un token: per impostazione predefinita gli spazi bianchi sono delimitatori. nextLine() legge invece il resto della riga conservando gli spazi interni ed escludendo il separatore finale. Se il nome può contenere spazi, usa nextLine. Una String composta da cifre rimane una String.',code:'Scanner a = new Scanner("Ada Rossi");\nSystem.out.println(a.next());     // Ada\n\nScanner b = new Scanner("Ada Rossi");\nSystem.out.println(b.nextLine()); // Ada Rossi',steps:['Disegna una posizione di lettura prima del primo carattere.','Con next fermati al delimitatore.','Con nextLine fermati solo alla fine della riga o dell’input.'],tip:'next = token; nextLine = resto della riga.'},
    {title:'La fine riga dopo un numero',text:'nextInt consuma il numero ma non necessariamente il separatore successivo. Se segue immediatamente Invio, nextLine vede il resto vuoto di quella stessa riga: restituisce "". Per leggere la riga seguente puoi consumare prima il resto con una nextLine dedicata. Non è un difetto casuale: dipende dalla posizione nel flusso.',code:'Scanner s = new Scanner("18\\nAda Rossi\\n");\nint eta = s.nextInt();\ns.nextLine(); // consuma il resto della riga del numero\nString nome = s.nextLine();\nSystem.out.println(nome); // Ada Rossi',steps:['nextInt legge 18 e si ferma prima della fine riga.','La prima nextLine legge un testo vuoto e consuma la fine riga.','La seconda nextLine legge Ada Rossi.'],tip:'Se non vedi una stringa, stampala tra parentesi: "[" + testo + "]".'},
    {title:'Numeri e input non valido',text:'Il metodo deve corrispondere al dato atteso. nextInt non converte parole né token fuori dal range int; può lanciare InputMismatchException. hasNextInt controlla il prossimo token senza consumarlo. I decimali dipendono dal locale: negli esempi con il punto imposta Locale.US.',code:'Scanner s = new Scanner("7.5");\ns.useLocale(java.util.Locale.US);\ndouble voto = s.nextDouble();\nSystem.out.println(voto); // 7.5\n\nScanner n = new Scanner("42");\nif (n.hasNextInt()) {\n    System.out.println(n.nextInt()); // 42\n}',steps:['Stabilisci tipo e formato del dato.','Se necessario imposta il locale per i decimali.','Valida prima di consumare quando l’input può essere errato.'],tip:'hasNextInt controlla ma non mangia il numero: dopo serve nextInt.'},
    {title:'print, println e concatenazione',text:'print non aggiunge una fine riga. println aggiunge il separatore di riga dopo il valore. Nessuno dei due aggiunge spazi automaticamente. Il simbolo + somma due numeri, ma concatena se uno degli operandi è una String; l’ordine e le parentesi contano.',code:'System.out.print("Ciao");\nSystem.out.print(" Ada");\nSystem.out.println("!");\nSystem.out.println("Somma: " + (2 + 3)); // Somma: 5\nSystem.out.println("Testo: " + 2 + 3);    // Testo: 23',steps:['Esegui le chiamate nell’ordine scritto.','Aggiungi solo spazi effettivamente contenuti nelle stringhe.','Sposta il cursore quando compare println o un carattere newline.'],tip:'Per una somma dentro una frase usa parentesi: "Totale: " + (a + b).'},
    {title:'Caratteri speciali e risorse',text:'Gli escape validi comprendono \\n per newline, \\t per tabulazione, \\\\ per un backslash e \\" per una virgoletta. Nei PDF compaiono alcuni escape di altri linguaggi: \\a e \\? non sono escape Java validi. Inoltre chiudere uno Scanner su System.in chiude anche lo standard input: evita di crearne e chiuderne molti senza una gestione chiara.',code:'System.out.println("Nome:\\tAda\\nCorso:\\tJava");\nSystem.out.println("Ha detto: \\"ciao\\"");\nSystem.out.println("Cartella: C:\\\\Studio");',steps:['Il sorgente usa due caratteri, come backslash+n, per rappresentare un carattere speciale.','Un backslash letterale richiede due backslash nel sorgente.','Le virgolette letterali vanno protette all’interno della stringa.'],tip:'Le sequenze di escape dipendono dal linguaggio: non copiarle da C o C++ senza verificarle.'}
  ],questions:input});
})();
